  if mask_state[i]==1:
    p_drop = base_drop_prob + compliance_fatigue_rate*Policy.days_since_start - enforcement_probability*0.1 - habit_strengthening_rate*(t - last_adoption_change_day[i])
    p_drop = clamp(p_drop, 0.0, 1.0)
    if Bernoulli(p_drop)==1: mask_state[i]=0; last_adoption_change_day[i]=t
    else if Bernoulli(1-p_stay_mask)==1: mask_state[i]=0; last_adoption_change_day[i]=t
  else:
    social_exposure = social_influence_strength*(layer_contact_weight_family*fam_frac_i + layer_contact_weight_work*work_frac_i + layer_contact_weight_comm*comm_frac_i)
    policy_effect = (Policy.current_policy_mode=='mandate')? policy_effect_size_mandate : ((Policy.current_policy_mode=='recommendation')? policy_effect_size_recommendation : 0.0)
    logit_p = baseline_adoption_logit + risk_perception_effect*risk_perception[i] + 1.0*received_info[i] + social_exposure + policy_effect
    p_adopt = sigmoid(logit_p)
    if RetailSupply.can_purchase[i] and Bernoulli(p_adopt)==1:
       RetailSupply.purchase_requests.add(i)
       mask_state[i]=1; last_adoption_change_day[i]=t
  # adherence update
  if mask_state[i]==1:
    adherence[i] = min(1.0, adherence[i]*(1 - adherence_decay_rate) + habit_strengthening_rate)
  else:
    adherence[i] = adherence[i]*(1 - adherence_decay_rate)

